768	    /// arena raises, so operators see one spelling either way).
769	    fn staging_arena(&self) -> Result<&sirius::StagingArena, String> {
770	        self.staging.as_ref().ok_or_else(|| {
771	            "exchange staging arena not configured (set SIRIUS_EXCHANGE_STAGING_BYTES)".to_string()
772	        })
773	    }
774	}
