1145	    /// The engine-actor mirror of the sirius crate's `packed_hop_matches_relay_hop`: a sender
1146	    /// parks its output, `export_packed_next` drains it into staging leases, and a receiver run
1147	    /// with `remote_inputs` delivers exactly the fixture rows — proving the staging info/lease/
1148	    /// release handle path, the ExportNext/DropParked plumbing, and the push-then-release
1149	    /// contract, GPU-side, without any network. Requires a GPU and
1150	    /// `SIRIUS_EXCHANGE_STAGING_BYTES` support.
1151	    #[test]
1152	    fn engine_pushes_staged_remote_batches() {
1153	        let _guard = crate::GPU_ENGINE_TEST_LOCK
1154	            .lock()
1155	            .unwrap_or_else(|err| err.into_inner());
1156	        ensure_parquet_extension_env();
1157	        // The arena is constructed at context bring-up, only when this is set.
1158	        // SAFETY: the GPU lock is held, so no other thread touches the environment here.
1159	        unsafe { std::env::set_var("SIRIUS_EXCHANGE_STAGING_BYTES", "64MiB") };
1160	
1161	        let dir = tempfile::tempdir().unwrap();
1162	        let path = dir.path().join("users.parquet");
1163	        write_users_parquet(&path);
1164	        let plan = local_files_plan(
1165	            path.to_str().unwrap(),
1166	            vec!["id".to_string(), "name".to_string()],
1167	        );
1168	
1169	        let engine = SiriusEngine::start(test_settings()).expect("bring up sirius engine");
1170	        let (base, capacity) = engine.staging_info().expect("staging arena info");
1171	        assert_ne!(base, 0);
1172	        assert_eq!(capacity, 64 << 20);
1173	
1174	        const EXCHANGE_NODE: i32 = 9;
1175	        let slot = SenderSlot {
1176	            fragment_instance_id: FragmentInstanceId::from_halves(3, 4),
1177	            node_id: EXCHANGE_NODE,
1178	            sender_id: 0,
1179	        };
1180	        engine
1181	            .run(FragmentRun {
1182	                plan: &plan,
1183	                inputs: Vec::new(),
1184	                remote_inputs: Vec::new(),
1185	                outputs: vec![slot],
1186	                broadcast: false,
1187	                hash_keys: Vec::new(),
1188	                label: FragmentLabel::default(),
1189	            })
1190	            .expect("run the sender fragment");
1191	
1192	        let mut staged = Vec::new();
1193	        while let Some(batch) = engine.export_packed_next(slot).expect("export packed") {
1194	            assert!(!batch.metadata.is_empty());
1195	            staged.push(batch);
1196	        }
1197	        assert!(!staged.is_empty(), "the sender parked batches to export");
1198	        // The packed bytes live in arena leases, independent of the parked fragment.
1199	        engine.drop_parked(slot).expect("drop the drained sender");
1200	        assert!(
1201	            engine.drop_parked(slot).is_err(),
1202	            "double drop must be a loud error"
1203	        );
1204	
1205	        let receiver = stream_plan(EXCHANGE_NODE, &[("id", false), ("name", true)]);
1206	        let result = engine
1207	            .run(FragmentRun {
1208	                plan: &receiver,
1209	                inputs: Vec::new(),
1210	                remote_inputs: vec![(EXCHANGE_NODE, 0, staged)],
1211	                outputs: Vec::new(),
1212	                broadcast: false,
1213	                hash_keys: Vec::new(),
1214	                label: FragmentLabel::default(),
1215	            })
1216	            .expect("execute the remote-fed receiver on GPU")
1217	            .expect("a result fragment returns rows");
1218	        let rows: usize = result.batches.iter().map(RecordBatch::num_rows).sum();
1219	        assert_eq!(rows, 3, "the staged remote hop preserved every row");
1220	
1221	        // Every lease went back (push-then-release), so the free list coalesced back to one
1222	        // whole-arena block and the next lease lands at the base.
1223	        let probe = engine.staging_lease(1024).expect("arena drained");
1224	        assert_eq!(probe, 0);
1225	        engine.staging_release(probe).unwrap();
1226	
1227	        // Keep the arena out of the other tests' context bring-ups.
1228	        // SAFETY: the GPU lock is still held.
1229	        unsafe { std::env::remove_var("SIRIUS_EXCHANGE_STAGING_BYTES") };
1230	    }
