1232	    /// The regression guard for the q02 lease starvation: a peer's `request_staging_lease`
1233	    /// lands while this CN's engine thread is busy running a fragment, and the old
1234	    /// engine-channel funnel made that lease wait for the whole run (forever, for a wedged
1235	    /// one). With the arena handle serving leases on the caller's thread, a lease taken while
1236	    /// the engine thread is occupied must return immediately. Requires a GPU.
1237	    #[test]
1238	    fn staging_lease_does_not_queue_behind_engine_work() {
1239	        let _guard = crate::GPU_ENGINE_TEST_LOCK
1240	            .lock()
1241	            .unwrap_or_else(|err| err.into_inner());
1242	        ensure_parquet_extension_env();
1243	        // The arena is constructed at context bring-up, only when this is set.
1244	        // SAFETY: the GPU lock is held, so no other thread touches the environment here.
1245	        unsafe { std::env::set_var("SIRIUS_EXCHANGE_STAGING_BYTES", "64MiB") };
1246	
1247	        let engine = SiriusEngine::start(test_settings()).expect("bring up sirius engine");
1248	        // Occupy the engine thread the way a long fragment run would (the raw-request door the
1249	        // dumped-plan harness also uses); anything funneled through the channel now waits.
1250	        let busy_for = std::time::Duration::from_secs(3);
1251	        engine
1252	            .requests
1253	            .lock()
1254	            .unwrap()
1255	            .as_ref()
1256	            .unwrap()
1257	            .send(EngineRequest::Sleep(busy_for))
1258	            .unwrap();
1259	
1260	        let started = std::time::Instant::now();
1261	        let offset = engine
1262	            .staging_lease(4096)
1263	            .expect("lease while the engine thread is busy");
1264	        engine
1265	            .staging_release(offset)
1266	            .expect("release while the engine thread is busy");
1267	        let (base, capacity) = engine.staging_info().expect("info while busy");
1268	        assert_ne!(base, 0);
1269	        assert_eq!(capacity, 64 << 20);
1270	        let elapsed = started.elapsed();
1271	        assert!(
1272	            elapsed < std::time::Duration::from_secs(1),
1273	            "staging calls queued behind engine work: served in {elapsed:?} while the engine \
1274	             thread was held for {busy_for:?}"
1275	        );
1276	
1277	        // Keep the arena out of the other tests' context bring-ups. Dropping `engine` below
1278	        // joins the engine thread, which finishes its sleep first — ordered teardown holds.
1279	        // SAFETY: the GPU lock is still held.
1280	        unsafe { std::env::remove_var("SIRIUS_EXCHANGE_STAGING_BYTES") };
1281	    }
