25	impl FragmentResult {
26	    /// Builds a result from its output batches (in fragment output order).
27	    pub fn new(batches: Vec<RecordBatch>) -> Self {
28	        Self { batches }
29	    }
30	
31	    /// The result batches in fragment output order.
32	    pub fn batches(&self) -> &[RecordBatch] {
33	        &self.batches
34	    }
35	}
