37	/// Where one sender fragment's output is parked until its receiver runs.
38	///
39	/// Keyed by the *receiver* it feeds, because that is what the rendezvous looks it up by: a sender
40	/// is addressed by the exchange it produces into, not by its own identity.
41	#[derive(Clone, Copy, Debug, PartialEq, Eq, Hash)]
42	pub struct SenderSlot {
43	    /// Receiver fragment instance the output is destined for.
44	    pub fragment_instance_id: FragmentInstanceId,
45	    /// Receiver `EXCHANGE_NODE` id, which is also the engine-side stream id.
46	    pub node_id: i32,
47	    /// Sender ordinal within that exchange's sender set.
48	    pub sender_id: i32,
49	}
