56	/// The exchange endpoint this CN is known by to the FE: advertised host plus brpc port.
57	///
58	/// A data-stream sink destination is classified against it before the sender runs: a match
59	/// keeps the exchange in-process, anything else is a remote CN.
60	#[derive(Clone, Debug)]
61	pub struct ExchangeIdentity {
62	    host: String,
63	    brpc_port: u16,
64	}
65	
66	impl ExchangeIdentity {
67	    /// Builds the identity from the CN's advertised host and brpc port (`ComputeNodeConfig`).
68	    pub fn new(host: impl Into<String>, brpc_port: u16) -> Self {
69	        Self {
70	            host: host.into(),
71	            brpc_port,
72	        }
73	    }
74	
75	    /// Hostname AND port equality — the stock BE's locality rule (`exchange_sink_operator.cpp`
76	    /// compares both), which is exactly what makes two CNs on one host see each other as remote.
77	    fn matches(&self, addr: &TNetworkAddress) -> bool {
78	        addr.hostname == self.host && addr.port == i32::from(self.brpc_port)
79	    }
80	
81	    /// `host:brpc_port` — the name peers address this CN by (its nixl agent name) and the
82	    /// `engine_name` its Quent telemetry reports, so a log line and a telemetry session agree.
83	    fn endpoint(&self) -> String {
84	        format!("{}:{}", self.host, self.brpc_port)
85	    }
86	}
