101	/// The remote drains one sender fragment posted to the transport thread, not yet joined.
102	#[must_use = "unjoined drains discard the failures the FE has to see"]
103	#[derive(Debug, Default)]
104	struct SenderDrains(Vec<DrainTicket>);
105	
106	impl SenderDrains {
107	    fn push(&mut self, ticket: DrainTicket) {
108	        self.0.push(ticket);
109	    }
110	
111	    /// Joins EVERY drain and returns the first failure.
112	    ///
113	    /// Never short-circuits on the first error, for two reasons. (1) A posted drain runs to
114	    /// completion on the transport thread whatever this thread does, and it is that drain — not
115	    /// this code — that performs the exactly-once `drop_parked` releasing its destination's
116	    /// claim on the parked fragment (nixl_transport.rs:669 on success, :306-317 on failure);
117	    /// abandoning a sibling would only lose its outcome, never cancel it. (2) The FE must see a
118	    /// failure whichever destination produced it. Every failure is logged; the first is returned.
119	    fn join(self) -> std::result::Result<(), String> {
120	        let mut first = None;
121	        for ticket in self.0 {
122	            if let Err(err) = ticket.join() {
123	                tracing::error!(error = %err, "a remote destination's drain failed");
124	                first.get_or_insert(err);
125	            }
126	        }
127	        first.map_or(Ok(()), Err)
128	    }
129	}
