131	/// What processing one fragment produced: the receivers whose sender sets it completed, and the
132	/// remote drains it posted. The two are deliberately separate so a caller can dispatch the
133	/// receivers *before* it joins the drains.
134	#[must_use]
135	#[derive(Debug, Default)]
136	struct FragmentOutcome {
137	    ready: Vec<ReadyFragment>,
138	    drains: SenderDrains,
139	}
140	
141	impl FragmentOutcome {
142	    /// A fragment that readied receivers but posted no remote drain.
143	    fn from_ready(ready: Vec<ReadyFragment>) -> Self {
144	        Self {
145	            ready,
146	            drains: SenderDrains::default(),
147	        }
148	    }
149	
150	    /// Joins the drains first, then yields the ready receivers — the shape the dispatch worker
151	    /// needs.
152	    ///
153	    /// The worker is single-threaded and is itself the thread that would run those receivers, so
154	    /// deferring the join there would buy no overlap; it would only move a drain failure out of
155	    /// `run_ready_fragment`, which is where a fragment failure gets attributed to its query. The
156	    /// overlap lives on the RPC path (`dispatch_then_join`), where the receiver runs on a
157	    /// different thread from the one that joins. Dropping `ready` when a drain failed matches
158	    /// the blocking loop this replaces: a sender that could not reach a remote destination has
159	    /// already failed the query.
160	    fn join_into_ready(self) -> std::result::Result<Vec<ReadyFragment>, String> {
161	        self.drains.join()?;
162	        Ok(self.ready)
163	    }
164	}
