271	    /// Reads `SIRIUS_CN_ASYNC_SENDER_DISPATCH` once at bring-up: `1`, `true` or `on` queue
272	    /// sender-only fragments (no exchange input, no RESULT_SINK) on the dispatch worker instead of
273	    /// running them inside their exec_plan_fragment RPC. Off by default.
274	    ///
275	    /// Why it exists: the FE deploys the first fragment instance of every node in one wave and
276	    /// waits for all of those RPCs before it deploys the remaining instances. A sender that runs
277	    /// inside its RPC holds that wave open for its whole scan, so on a gather (q06: partial ->
278	    /// EXCHANGE UNPARTITIONED) the node that also hosts the merge fragment only receives its own
279	    /// scan after every other node's scan has finished. Measured on 4 GB200 CNs at SF1000: three
280	    /// scans started together and the fourth 726 ms later, right after the last `transmitted
281	    /// batches via nixl`. Returning as soon as the fragment is queued lets every scan start in the
282	    /// same wave.
283	    ///
284	    /// Why it is off by default: a queued sender's failure (a malformed sink, an untranslatable
285	    /// plan, a failed remote drain) is attributed through `results.fail_query`, which only reaches
286	    /// result instances reserved on this node. When the result fragment lives on another node the
287	    /// FE learns of the failure through its query timeout instead of this RPC's status. Flip the
288	    /// default once a sender failure is forwarded to the receiver's node.
289	    fn async_sender_dispatch_from_env() -> bool {
290	        matches!(
291	            std::env::var("SIRIUS_CN_ASYNC_SENDER_DISPATCH").as_deref(),
292	            Ok("1") | Ok("true") | Ok("TRUE") | Ok("on") | Ok("ON")
293	        )
294	    }
295	
296	    /// Overrides the bring-up setting; tests use it to exercise the queued path without touching
297	    /// the process environment.
298	    #[cfg(test)]
299	    pub(crate) fn set_async_sender_dispatch(&self, enabled: bool) {
300	        self.core
301	            .async_sender_dispatch
302	            .store(enabled, std::sync::atomic::Ordering::Relaxed);
303	    }
304	
305	    /// Queues a sender-only fragment on the dispatch worker. Returns `Ok(false)` when the
306	    /// fragment must take the inline path (exchange receiver, RESULT_SINK root, survey mode, or
307	    /// the switch is off); descriptor tables are resolved at arrival either way, so the FE's
308	    /// per-query descriptor cache protocol sees the same order as before.
309	    fn try_dispatch_sender(
310	        &self,
311	        params: &TExecPlanFragmentParams,
312	    ) -> std::result::Result<bool, String> {
313	        if !self
314	            .core
315	            .async_sender_dispatch
316	            .load(std::sync::atomic::Ordering::Relaxed)
317	            || std::env::var_os("SIRIUS_CN_TRANSLATE_ONLY").is_some()
318	            || !ServiceCore::receiver_exchanges(params)?.is_empty()
319	            || ServiceCore::is_mysql_result_sink(params)?
320	        {
321	            return Ok(false);
322	        }
323	        let params = self.core.resolve_descriptor_table(params)?;
324	        self.dispatch(ReadyFragment {
325	            params,
326	            inputs: Vec::new(),
327	        })?;
328	        Ok(true)
329	    }
330	
331	    /// Hands a ready receiver to the dispatch worker so this RPC thread returns immediately
332	    /// instead of blocking on the receiver's whole execution.
333	    fn dispatch(&self, ready: ReadyFragment) -> std::result::Result<(), String> {
334	        self.ready_fragments.send(ready).map_err(|_| {
335	            "fragment dispatch worker has exited; cannot execute receiver fragment".to_string()
336	        })
337	    }
338	
339	    /// Dispatches every receiver this fragment readied, THEN joins its remote drains.
340	    ///
341	    /// The order is the whole change: dispatch puts the receiver on the worker thread while the
342	    /// transport thread is still draining this sender's remote destinations, instead of the
343	    /// receiver waiting out the full (N-1)-destination drain first. The RPC still does not
344	    /// return until every drain has been joined — the FE may only be told the sender succeeded
345	    /// once each destination's copy is actually across the wire.
346	    ///
347	    /// A receiver dispatched here can now run concurrently with its own query's drains. That
348	    /// costs nothing in correctness (its sender set was already complete, so it reads no data
349	    /// the drains produce) but it does mean the parked batches of the not-yet-drained
350	    /// destinations stay resident while it computes — the deliberate memory-for-latency trade.
351	    fn dispatch_then_join(&self, outcome: FragmentOutcome) -> std::result::Result<(), String> {
352	        let mut dispatch_error = None;
353	        for ready in outcome.ready {
354	            if let Err(err) = self.dispatch(ready) {
355	                dispatch_error.get_or_insert(err);
356	            }
357	        }
358	        // Joined unconditionally, even when dispatch failed: the drains are already in flight.
359	        let drain_result = outcome.drains.join();
360	        match (drain_result, dispatch_error) {
361	            (Ok(()), None) => Ok(()),
362	            (Ok(()), Some(dispatch)) => Err(dispatch),
363	            // A drain failure names the destination and the transport fault, so it is the more
364	            // useful cause to hand the FE; a dispatch failure only ever means "this CN is
365	            // shutting down". Report the drain error, keep the other in the log.
366	            (Err(drain), dispatch) => {
367	                if let Some(dispatch) = dispatch {
368	                    tracing::error!(error = %dispatch, "receiver dispatch also failed");
369	                }
370	                Err(drain)
371	            }
372	        }
373	    }
374	}
