376	/// Executes ready receiver fragments sequentially, off the RPC threads.
377	///
378	/// Exits when every service clone has dropped its sender; the worker then releases its core
379	/// handle (and with it the executor), keeping engine teardown ordered.
380	fn dispatch_worker(core: Arc<ServiceCore>, inbox: mpsc::Receiver<ReadyFragment>) {
381	    while let Ok(ready) = inbox.recv() {
382	        // A receiver can itself be a sender whose completion readies further receivers (a
383	        // middle fragment, possibly fanning out); chase the whole set inline — this thread is
384	        // already off the RPC path.
385	        let mut queue = vec![ready];
386	        while let Some(ready) = queue.pop() {
387	            queue.extend(core.run_ready_fragment(ready));
388	        }
389	    }
390	}
