392	impl PInternalService for SiriusComputeNodeService {
393	    /// Handles a single FE-dispatched plan fragment thrift attachment. A root fragment without an
394	    /// exchange executes immediately; an exchange receiver waits for its local sender fragments.
395	    /// The final rows are buffered for `fetch_data`.
396	    #[instrument(skip_all)]
397	    async fn exec_plan_fragment(
398	        &self,
399	        request: PExecPlanFragmentRequest,
400	        attachment: Vec<u8>,
401	    ) -> Result<crate::prpc::Reply<PExecPlanFragmentResult>, crate::prpc::Error> {
402	        // Translate + execute on a blocking worker, not the BRPC current-thread runtime: a real GPU
403	        // executor blocks for the whole query, so running it inline would stall fetch_data,
404	        // connection cleanup, and shutdown cancellation until it returns.
405	        let protocol = request.attachment_protocol;
406	        let service = self.clone();
407	        let outcome = tokio::task::spawn_blocking(move || {
408	            service.exec_single_attachment(protocol.as_deref(), &attachment)
409	        })
410	        .await;
411	        let status = match outcome {
412	            Ok(Ok(())) => Self::ok_status(),
413	            Ok(Err(err)) => Self::internal_error(err),
414	            Err(join_err) => {
415	                Self::internal_error(format!("fragment execution task panicked: {join_err}"))
416	            }
417	        };
418	        Ok(Self::exec_plan_result(status).into())
419	    }
420	
421	    /// Handles FE batch fragment dispatch: translate every per-instance fragment and execute the
422	    /// RESULT_SINK roots among them.
423	    #[instrument(skip_all)]
424	    async fn exec_batch_plan_fragments(
425	        &self,
426	        request: PExecBatchPlanFragmentsRequest,
427	        attachment: Vec<u8>,
428	    ) -> Result<crate::prpc::Reply<PExecBatchPlanFragmentsResult>, crate::prpc::Error> {
429	        // Like `exec_plan_fragment`, an instance can run a RESULT_SINK fragment on the GPU, so
430	        // offload to a blocking worker rather than blocking the BRPC current-thread runtime.
431	        let protocol = request.attachment_protocol;
432	        let service = self.clone();
433	        let outcome = tokio::task::spawn_blocking(move || {
434	            service.translate_batch_attachment(protocol.as_deref(), &attachment)
435	        })
436	        .await;
437	        let status = match outcome {
438	            Ok(Ok(())) => Self::ok_status(),
439	            Ok(Err(err)) => Self::internal_error(err),
440	            Err(join_err) => Self::internal_error(format!(
441	                "batch fragment execution task panicked: {join_err}"
442	            )),
443	        };
444	        Ok(PExecBatchPlanFragmentsResult {
