450	    /// Best-effort cancellation stub: acknowledges the FE with OK so its shared jprotobuf
451	    /// channel stays healthy — the default unrouted reply is a PRPC-level error frame, and the
452	    /// FE reaps the timed-out future in a way that misattributes later replies on the channel.
453	    /// A still-waiting result entry is failed so a `fetch_data` long-poll returns immediately.
454	    /// Real teardown (aborting the engine run, freeing GPU buffers, dropping parked exchange
455	    /// state) is a separate work item.
456	    #[instrument(skip_all)]
457	    async fn cancel_plan_fragment(
458	        &self,
459	        request: PCancelPlanFragmentRequest,
460	        _attachment: Vec<u8>,
461	    ) -> Result<crate::prpc::Reply<PCancelPlanFragmentResult>, crate::prpc::Error> {
462	        let id = FragmentInstanceId::from(&request.finst_id);
463	        info!(
464	            fragment_instance_id = %id,
465	            query_id = ?request.query_id.as_ref().map(FragmentInstanceId::from),
466	            cancel_reason = request.cancel_reason,
467	            error_message = ?request.error_message,
468	            "acknowledging cancel_plan_fragment (best-effort: no engine-side abort yet)"
469	        );
470	        let mut reason = format!("fragment instance {id} was cancelled by the FE");
471	        if let Some(message) = request.error_message.as_ref().filter(|msg| !msg.is_empty()) {
472	            reason = format!("{reason}: {message}");
473	        }
474	        self.core.results.cancel(id, reason);
475	        Ok(PCancelPlanFragmentResult {
476	            status: Self::ok_status(),
477	        }
478	        .into())
