481	    /// Returns buffered fragment results to the FE, which polls this until end-of-stream. The
482	    /// serialized `TResultBatch` rows ride in the BRPC response attachment.
483	    #[instrument(skip_all)]
484	    async fn fetch_data(
485	        &self,
486	        request: PFetchDataRequest,
487	        _attachment: Vec<u8>,
488	    ) -> Result<crate::prpc::Reply<PFetchDataResult>, crate::prpc::Error> {
489	        let id = FragmentInstanceId::from(&request.finst_id);
490	        // Long-poll: receivers execute on the dispatch thread now, so a reserved result may not
491	        // be ready when the FE's first poll arrives. Block off the runtime until it is — every
492	        // reply consumes a packet-sequence slot in the FE's ResultReceiver, so a not-ready reply
493	        // would desync the counter and cancel the query ("expect=1, receive=0").
494	        let core = self.core.clone();
495	        let outcome = match tokio::task::spawn_blocking(move || {
496	            core.results
497	                .wait_ready(id, std::time::Duration::from_secs(600))
498	        })
499	        .await
500	        {
501	            Ok(outcome) => outcome,
502	            Err(join_err) => {
503	                return Ok(Self::fetch_data_result(
504	                    Self::internal_error(format!("fetch_data wait task panicked: {join_err}")),
505	                    0,
506	                    true,
507	                )
508	                .into());
509	            }
510	        };
511	        // An unknown id is an error, not EOS: it means this CN never buffered a result for the
512	        // fragment the FE is polling (wrong id, or a dispatch/result-sink path that did not run),
513	        // and StarRocks treats a missing result buffer as a failure rather than an empty result.
514	        let Some(outcome) = outcome else {
515	            return Ok(Self::fetch_data_result(
516	                Self::internal_error(format!("no buffered result for fragment instance {id}")),
517	                0,
518	                true,
519	            )
520	            .into());
521	        };
522	        match outcome {
523	            FetchOutcome::Failed(cause) => Ok(Self::fetch_data_result(
524	                Self::internal_error(format!("fragment instance {id} failed: {cause}")),
525	                0,
526	                true,
527	            )
528	            .into()),
529	            FetchOutcome::Rows {
530	                batch: Some(batch),
531	                packet_seq,
532	                eos,
533	            } => match batch.to_binary() {
534	                Ok(bytes) => Ok(crate::prpc::Reply::with_attachment(
535	                    Self::fetch_data_result(Self::ok_status(), packet_seq, eos),
536	                    bytes,
537	                )),
538	                Err(err) => {
539	                    Ok(Self::fetch_data_result(Self::internal_error(err), packet_seq, true).into())
540	                }
541	            },
542	            FetchOutcome::Rows {
543	                batch: None,
544	                packet_seq,
545	                eos,
546	            } => Ok(Self::fetch_data_result(Self::ok_status(), packet_seq, eos).into()),
547	        }
548	    }
