703	    /// Deserializes one binary-thrift TExecPlanFragmentParams attachment and processes it,
704	    /// handing any completed receiver to the dispatch worker.
705	    fn exec_single_attachment(
706	        &self,
707	        protocol: Option<&str>,
708	        attachment: &[u8],
709	    ) -> std::result::Result<(), String> {
710	        Self::ensure_binary_protocol(protocol)?;
711	        let params = Self::deserialize_binary::<TExecPlanFragmentParams>(attachment)
712	            .map_err(|err| format!("failed to deserialize TExecPlanFragmentParams: {err}"))?;
713	        if self.try_dispatch_sender(&params)? {
714	            return Ok(());
715	        }
716	        self.dispatch_then_join(self.core.process_fragment(&params)?)
717	    }
