719	    /// Records one remote exchange frame in the rendezvous (or releases a canary lease), handing
720	    /// a completed receiver to the dispatch worker.
721	    fn handle_transmit_packed(
722	        &self,
723	        params: &PTransmitPackedParams,
724	        attachment: Vec<u8>,
725	    ) -> std::result::Result<(), String> {
726	        if params.canary() {
727	            // The bandwidth canary writes into a lease nothing will consume; release it without
728	            // touching the rendezvous or the engine's input streams.
729	            let offset = params.offset.ok_or_else(|| {
730	                "canary transmit_packed frame carries no lease offset".to_string()
731	            })?;
732	            return self.core.executor.staging_release(offset);
733	        }
734	        let finst_id = params
735	            .finst_id
736	            .as_ref()
737	            .ok_or_else(|| "transmit_packed frame carries no finst_id".to_string())?;
738	        let node_id = params
739	            .node_id
740	            .ok_or_else(|| "transmit_packed frame carries no node_id".to_string())?;
741	        let sender_id = params
742	            .sender_id
743	            .ok_or_else(|| "transmit_packed frame carries no sender_id".to_string())?;
744	        let seq = params
745	            .seq
746	            .ok_or_else(|| "transmit_packed frame carries no seq".to_string())?;
747	        let eos = params.eos.unwrap_or(false);
748	        let key = ExchangeKey {
749	            fragment_instance_id: FragmentInstanceId::from(finst_id),
750	            node_id,
751	        };
752	        // The pack metadata rides the attachment; its presence is what makes a frame a batch.
753	        let batch = if attachment.is_empty() {
754	            None
755	        } else {
756	            let length = params.length.ok_or_else(|| {
757	                "transmit_packed batch frame carries no payload length".to_string()
758	            })?;
759	            let offset = params
760	                .offset
761	                .ok_or_else(|| "transmit_packed batch frame carries no lease offset".to_string())?;
762	            Some(StagedBatch {
763	                metadata: attachment,
764	                offset,
765	                len: length,
766	                // None from a sender that predates the wire field: the receiver then skips the
767	                // stream's cardinality declaration instead of failing the frame.
768	                rows: params.rows,
769	            })
770	        };
771	        tracing::debug!(
772	            receiver_fragment_instance_id = %key.fragment_instance_id,
773	            stream_id = key.node_id,
774	            sender_id,
775	            seq,
776	            eos,
777	            batch_bytes = batch.as_ref().map(|batch| batch.len),
778	            rows = batch.as_ref().and_then(|batch| batch.rows),
779	            "received remote exchange frame"
780	        );
781	        if eos {
782	            // The receiver-side stitch for the sender's "transmitted batches via nixl" line: the
783	            // eos frame's seq is the number of batch frames that preceded it on this stream.
784	            info!(
785	                receiver_fragment_instance_id = %key.fragment_instance_id,
786	                stream_id = key.node_id,
787	                sender_id,
788	                frames = seq,
789	                "remote exchange stream ended"
790	            );
791	        }
792	        if let Some(ready) = self.core.exchanges.push_remote_frame(
793	            key,
794	            sender_id,
795	            seq,
796	            eos,
797	            params.column_names.clone(),
798	            batch,
799	        )? {
800	            self.dispatch(ready)?;
801	        }
802	        Ok(())
803	    }
804	}
