806	impl ServiceCore {
807	    /// Executes an `ADMIN EXECUTE` script: parse, then run each command on the fragment
808	    /// executor in order, stopping at the first failure. Returns one summary line per command
809	    /// ('\n'-joined — the FE renders each line as a result row).
810	    fn handle_execute_command(
811	        &self,
812	        request: &ExecuteCommandRequestPb,
813	    ) -> std::result::Result<String, String> {
814	        // The FE hardcodes this command name for ADMIN EXECUTE (ExecuteScriptExecutor.java);
815	        // reject anything else by name rather than guessing at its payload.
816	        match request.command.as_deref() {
817	            Some("execute_script") => {}
818	            other => {
819	                return Err(format!(
820	                    "unsupported execute_command command {other:?}; this CN only accepts \
821	                     'execute_script' (ADMIN EXECUTE ON <node_id> '<script>')"
822	                ));
823	            }
824	        }
825	        let script = request
826	            .params
827	            .as_deref()
828	            .filter(|params| !params.trim().is_empty())
829	            .ok_or_else(|| {
830	                "empty script; supported commands: pin_table path=<file-or-glob> \
831	                 tier=gpu|host name=<name> [cols=c1,c2,...] [format=parquet|duckdb] \
832	                 [schema=<schema>] | unpin_table <name>"
833	                    .to_string()
834	            })?;
835	        // Bound parse/log cost; the grammar never needs scripts anywhere near this size.
836	        const MAX_SCRIPT_BYTES: usize = 64 * 1024;
837	        if script.len() > MAX_SCRIPT_BYTES {
838	            return Err(format!(
839	                "script is {} bytes; the CN caps admin scripts at {MAX_SCRIPT_BYTES}",
840	                script.len()
841	            ));
842	        }
843	        tracing::info!(script, "execute_command admin script accepted");
844	        let commands = crate::admin_command::parse_script(script)?;
845	        let total = commands.len();
846	        let mut lines = Vec::with_capacity(total);
847	        for (index, command) in commands.into_iter().enumerate() {
848	            let line = match &command {
849	                crate::admin_command::AdminCommand::PinTable(spec) => self.executor.pin_table(spec),
850	                crate::admin_command::AdminCommand::UnpinTable { name } => {
851	                    self.executor.unpin_table(name)
852	                }
853	            }
854	            .map_err(|err| format!("command {} of {total}: {err}", index + 1))?;
855	            lines.push(line);
856	        }
857	        let outcome = lines.join("\n");
858	        tracing::info!(outcome, "execute_command admin script finished");
859	        Ok(outcome)
860	    }
861	
862	    /// Runs one dispatched receiver, parking a failure where `fetch_data` can see it. Returns
863	    /// the next receiver when this fragment's own sink completed another sender set.
864	    fn run_ready_fragment(&self, ready: ReadyFragment) -> Vec<ReadyFragment> {
865	        let id = Self::fragment_instance_id(&ready.params);
866	        let query_id = Self::query_id(&ready.params);
867	        let is_result_fragment = matches!(Self::is_mysql_result_sink(&ready.params), Ok(true));
868	        // `join_into_ready` keeps this fragment's own remote drains inside this call, so a drain
869	        // failure is attributed to the same query as any other failure of this fragment.
870	        match self
871	            .execute_ready_fragment(ready)
872	            .and_then(FragmentOutcome::join_into_ready)
873	        {
874	            Ok(next) => next,
875	            Err(error) => {
876	                match (id, query_id) {
877	                    (Some(id), Some(query_id)) => {
878	                        if is_result_fragment {
879	                            // The FE polls fetch_data on this id; its reserved entry becomes
880	                            // the error instead of waiting forever.
881	                            tracing::error!(fragment_instance_id = %id, error = %error, "dispatched result fragment failed");
882	                        } else {
883	                            // An intermediate receiver has no FE-polled entry of its own, so
884	                            // its failure must reach the query's result-fragment instances —
885	                            // otherwise the FE polls until its timeout and the stalled
886	                            // fetch_data wedges this CN's whole frame loop.
887	                            tracing::error!(
888	                                fragment_instance_id = %id,
889	                                error = %error,
890	                                "dispatched intermediate receiver fragment failed; failing the query's result fragments"
891	                            );
892	                        }
893	                        // Fails this id, every reserved result instance of the query, and
894	                        // records the failure so a result fragment arriving later fails on
895	                        // registration instead of waiting on senders that never deliver.
896	                        self.results.fail_query(query_id, id, error);
897	                    }
898	                    (Some(id), None) => {
899	                        // Defensive: exec params carry both ids or neither, so this arm should
900	                        // be unreachable. Park the error under the instance id at least.
901	                        tracing::error!(fragment_instance_id = %id, error = %error, "dispatched receiver fragment without a query_id failed");
902	                        self.results.fail(id, error);
903	                    }
904	                    (None, _) => {
905	                        tracing::error!(error = %error, "dispatched receiver fragment without a fragment_instance_id failed");
906	                    }
907	                }
908	                Vec::new()
909	            }
910	        }
911	    }
912	
913	    /// Processes one fragment and buffers supported RESULT_SINK rows for later `fetch_data`.
914	    /// Shared by single and batch dispatch; exchange receivers are registered until their local
915	    /// sender output is materialized. Returns a receiver whose sender set this fragment
916	    /// completed — the caller decides where it executes (RPC handlers hand it to the dispatch
917	    /// worker; the worker itself runs it inline).
918	    fn process_fragment(
919	        &self,
920	        params: &TExecPlanFragmentParams,
921	    ) -> std::result::Result<FragmentOutcome, String> {
922	        let params = self.resolve_descriptor_table(params)?;
923	        let dump_seq = Self::dump_fragment(&params);
924	        // Survey mode: accept every fragment so the FE dispatches (and we dump) the whole
925	        // plan even when translation fails. Queries still fail at fetch_data.
926	        if std::env::var_os("SIRIUS_CN_TRANSLATE_ONLY").is_some() {
927	            if let Err(err) = self.translate_fragment_logged(&params, dump_seq) {
928	                tracing::warn!(error = %err, "translate-only mode: accepting untranslatable fragment");
929	            }
930	            return Ok(FragmentOutcome::default());
931	        }
932	        let expected_senders = Self::receiver_exchanges(&params)?;
933	        if !expected_senders.is_empty() {
934	            let fragment_instance_id = Self::fragment_instance_id(&params)
935	                .ok_or_else(|| "exchange receiver is missing a fragment_instance_id".to_string())?;
936	            if Self::is_mysql_result_sink(&params)? {
937	                let query_id = Self::query_id(&params)
938	                    .ok_or_else(|| "exchange receiver is missing a query_id".to_string())?;
939	                self.results.reserve(fragment_instance_id, query_id);
940	            }
941	            return Ok(FragmentOutcome::from_ready(
942	                self.exchanges
943	                    .register_receiver(fragment_instance_id, expected_senders, params)?
944	                    .into_iter()
945	                    .collect(),
946	            ));
947	        }
948	
949	        let translated = self.translate_fragment_logged(&params, dump_seq)?;
950	        self.execute_fragment(&params, translated)
951	    }
