1257	                "DATA_STREAM_SINK destination for fragment instance {} has no brpc_server address",
1258	                FragmentInstanceId::from(&destination.fragment_instance_id)
1259	            )
1260	        })?;
1261	        if self.identity.matches(brpc_server) {
1262	            Ok(DestinationRoute::Local)
1263	        } else {
1264	            Ok(DestinationRoute::Remote {
1265	                host: brpc_server.hostname.clone(),
1266	                brpc_port: u16::try_from(brpc_server.port).map_err(|_| {
1267	                    format!(
1268	                        "destination brpc port {} is not a valid TCP port",
1269	                        brpc_server.port
1270	                    )
1271	                })?,
1272	            })
1273	        }
1274	    }
