1479	    /// Classifies the fragment output sink: `Ok(true)` for a MySQL text-protocol RESULT_SINK this
1480	    /// CN can encode, `Ok(false)` for a non-result sink, and `Err` for a
1481	    /// RESULT_SINK whose format is not supported yet (binary rows, HTTP/FILE/Arrow Flight, etc.).
1482	    /// The encoder only emits MySQL text rows, so other result-sink formats must be rejected
1483	    /// rather than returned in the wrong wire format.
1484	    fn is_mysql_result_sink(params: &TExecPlanFragmentParams) -> std::result::Result<bool, String> {
1485	        let Some(sink) = params
1486	            .fragment
1487	            .as_ref()
1488	            .and_then(|fragment| fragment.output_sink.as_ref())
1489	        else {
1490	            return Ok(false);
1491	        };
1492	        if sink.type_ != TDataSinkType::RESULT_SINK {
1493	            return Ok(false);
1494	        }
1495	        // A RESULT_SINK with no nested detail defaults to MySQL text rows.
1496	        let Some(result_sink) = sink.result_sink.as_ref() else {
1497	            return Ok(true);
1498	        };
1499	        if matches!(result_sink.is_binary_row, Some(true)) {
1500	            return Err("binary-row result sinks are not supported yet".to_string());
1501	        }
1502	        match result_sink.type_ {
1503	            None | Some(TResultSinkType::MYSQL_PROTOCAL) => Ok(true),
1504	            Some(other) => Err(format!("result sink type {other:?} is not supported yet")),
1505	        }
1506	    }
