1508	    /// Names a thrift sink type for an operator. The generated type is a newtype over the wire
1509	    /// number, so its `Debug` prints `TDataSinkType(7)` — useless in an FE error message.
1510	    fn data_sink_type_name(sink_type: TDataSinkType) -> String {
1511	        let name = match sink_type {
1512	            TDataSinkType::DATA_STREAM_SINK => "DATA_STREAM_SINK",
