1535	    /// Runs one fragment on the executor, bracketed by this CN's start/finish lines. Those lines
1536	    /// carry the StarRocks query id, the fragment instance id, and this CN's exchange endpoint —
1537	    /// the same three names the engine's Quent Query label (`<query id>:<fragment instance id>`
1538	    /// in the group `<query id>`, engine `<endpoint>`) and the transport's transmit line use — so
1539	    /// one query's halves on different CNs can be stitched from logs and telemetry alike.
1540	    fn run_labeled(
1541	        &self,
1542	        role: &'static str,
1543	        run: FragmentRun<'_>,
1544	    ) -> std::result::Result<Option<FragmentResult>, String> {
1545	        let (query_id, fragment_instance_id) = run.label.log_ids();
1546	        let cn = self.identity.endpoint();
1547	        let inputs = run.inputs.len() + run.remote_inputs.len();
1548	        let outputs = run.outputs.len();
1549	        info!(
1550	            %query_id,
1551	            %fragment_instance_id,
1552	            %cn,
1553	            role,
1554	            inputs,
1555	            outputs,
1556	            "fragment run started"
1557	        );
1558	        let started = std::time::Instant::now();
1559	        let result = self.executor.run(run);
1560	        let elapsed_ms = started.elapsed().as_millis() as u64;
1561	        match &result {
1562	            Ok(_) => info!(
1563	                %query_id,
1564	                %fragment_instance_id,
1565	                %cn,
1566	                role,
1567	                elapsed_ms,
1568	                "fragment run finished"
1569	            ),
1570	            Err(error) => info!(
1571	                %query_id,
1572	                %fragment_instance_id,
1573	                %cn,
1574	                role,
1575	                elapsed_ms,
1576	                %error,
1577	                "fragment run failed"
1578	            ),
1579	        }
1580	        result
1581	    }
