1622	    /// Deserializes a FE batch attachment and merges common params into each instance, handing
1623	    /// any completed receiver to the dispatch worker.
1624	    fn translate_batch_attachment(
1625	        &self,
1626	        protocol: Option<&str>,
1627	        attachment: &[u8],
1628	    ) -> std::result::Result<(), String> {
1629	        Self::ensure_binary_protocol(protocol)?;
1630	        let batch = Self::deserialize_binary::<TExecBatchPlanFragmentsParams>(attachment)
1631	            .map_err(|err| format!("failed to deserialize TExecBatchPlanFragmentsParams: {err}"))?;
1632	        let common = batch
1633	            .common_param
1634	            .as_ref()
1635	            .ok_or_else(|| "TExecBatchPlanFragmentsParams.common_param is missing".to_string())?;
1636	        let instances = batch.unique_param_per_instance.as_ref().ok_or_else(|| {
1637	            "TExecBatchPlanFragmentsParams.unique_param_per_instance is missing".to_string()
1638	        })?;
1639	
1640	        if instances.is_empty() {
1641	            return Err(
1642	                "TExecBatchPlanFragmentsParams.unique_param_per_instance is empty".to_string(),
1643	            );
1644	        }
1645	
1646	        for (idx, instance) in instances.iter().enumerate() {
1647	            let mut params = instance.clone();
1648	            if params.desc_tbl.is_none() {
1649	                params.desc_tbl = common.desc_tbl.clone();
1650	            }
1651	            if params.query_globals.is_none() {
1652	                params.query_globals = common.query_globals.clone();
1653	            }
1654	            if params.query_options.is_none() {
1655	                params.query_options = common.query_options.clone();
1656	            }
1657	            if params.resource_info.is_none() {
1658	                params.resource_info = common.resource_info.clone();
1659	            }
1660	
1661	            if self
1662	                .try_dispatch_sender(&params)
1663	                .map_err(|err| format!("fragment {idx}: {err}"))?
1664	            {
1665	                continue;
1666	            }
1667	            let outcome = self
1668	                .core
1669	                .process_fragment(&params)
1670	                .map_err(|err| format!("fragment {idx}: {err}"))?;
1671	            // Per instance, exactly like the single-attachment path: a batch instance's drains
1672	            // are joined before the next instance is processed, so instance ordering — and the
1673	            // `fragment {idx}` attribution of a failure — is unchanged.
1674	            self.dispatch_then_join(outcome)
1675	                .map_err(|err| format!("fragment {idx}: {err}"))?;
1676	        }
1677	
1678	        Ok(())
1679	    }
