1681	    /// Extracts the parquet paths from the binary-thrift attachment and infers their common
1682	    /// schema. The FE sends one request covering every FILES() file, one range per file.
1683	    async fn file_schema_from_attachment(
1684	        attachment: &[u8],
1685	    ) -> std::result::Result<Vec<PSlotDescriptor>, String> {
1686	        let request = Self::deserialize_binary::<TGetFileSchemaRequest>(attachment)
1687	            .map_err(|err| format!("failed to deserialize TGetFileSchemaRequest: {err}"))?;
1688	        let broker = request.scan_range.broker_scan_range.ok_or_else(|| {
1689	            "TGetFileSchemaRequest scan_range carries no broker_scan_range".to_string()
1690	        })?;
1691	        if broker.ranges.is_empty() {
1692	            return Err("broker_scan_range carries no file ranges".to_string());
1693	        }
1694	        let paths = broker
1695	            .ranges
1696	            .into_iter()
1697	            .map(|range| {
1698	                if range.format_type != TFileFormatType::FORMAT_PARQUET {
1699	                    return Err(format!(
1700	                        "unsupported file format {:?} for '{}'; only parquet schema inference is implemented",
1701	                        range.format_type, range.path
1702	                    ));
1703	                }
1704	                Ok(range.path)
1705	            })
1706	            .collect::<std::result::Result<Vec<_>, String>>()?;
1707	        crate::file_schema::parquet_files_schema(&paths).await
1708	    }
