1710	    /// Deserializes a thrift struct using the StarRocks binary attachment protocol.
1711	    fn deserialize_binary<T>(bytes: &[u8]) -> thrift::Result<T>
1712	    where
1713	        T: TSerializable,
1714	    {
1715	        let mut channel = TBufferChannel::with_capacity(bytes.len(), 0);
1716	        let bytes_copied = channel.set_readable_bytes(bytes);
1717	        if bytes_copied != bytes.len() {
1718	            return Err(thrift::Error::Application(thrift::ApplicationError::new(
1719	                thrift::ApplicationErrorKind::Unknown,
1720	                "failed to stage complete thrift payload".to_string(),
1721	            )));
1722	        }
1723	        let mut protocol = TBinaryInputProtocol::new(channel, true);
1724	        T::read_from_in_protocol(&mut protocol)
1725	    }
