2609	    /// Collects the specs a fake transport was handed, answering each with `outcome`.
2610	    ///
2611	    /// `recv_timeout` rather than `recv`: a regression that stops posting a drain must fail the
2612	    /// test, never hang the suite.
2613	    fn drain_specs(
2614	        requests: mpsc::Receiver<crate::nixl_transport::TransportRequest>,
2615	        mut outcome: impl FnMut(usize) -> Result<(), String>,
2616	    ) -> Vec<RemoteSendSpec> {
2617	        let mut specs = Vec::new();
2618	        while let Ok(request) =
2619	            requests.recv_timeout(std::time::Duration::from_millis(if specs.is_empty() {
2620	                10_000
2621	            } else {
2622	                1_000
2623	            }))
2624	        {
2625	            match request {
2626	                crate::nixl_transport::TransportRequest::SendFragment { spec, respond } => {
2627	                    let _ = respond.send(outcome(specs.len()));
2628	                    specs.push(spec);
2629	                }
2630	                _ => panic!("the sender flow only posts drains"),
2631	            }
2632	        }
2633	        specs
2634	    }
