3308	    /// Builds the three-fragment chain used by the failure-propagation tests: a result-sink root
3309	    /// reading exchange 9, a middle receiver reading exchange 7 and sinking into 9, and a leaf
3310	    /// scan sinking into 7. All three share `query_id`.
3311	    fn propagation_chain(
3312	        query_id: &TUniqueId,
3313	        root_id: &TUniqueId,
3314	        middle_id: &TUniqueId,
3315	        leaf_id: &TUniqueId,
3316	    ) -> (
3317	        TExecPlanFragmentParams,
3318	        TExecPlanFragmentParams,
3319	        TExecPlanFragmentParams,
3320	    ) {
3321	        let mut root = fragment_params(Some(exchange_plan(9, 0)), Some(desc_table()));
3322	        root.fragment.as_mut().unwrap().output_sink = Some(result_sink());
3323	        let mut root_exec = exec_params(query_id.clone(), root_id.clone());
3324	        root_exec.per_exch_num_senders.insert(9, 1);
3325	        root.params = Some(root_exec);
3326	
3327	        let mut middle = fragment_params(Some(exchange_plan(7, 0)), Some(desc_table()));
3328	        middle.fragment.as_mut().unwrap().output_sink = Some(data_stream_sink(9));
3329	        let mut middle_exec = exec_params(query_id.clone(), middle_id.clone());
3330	        middle_exec.per_exch_num_senders.insert(7, 1);
3331	        middle_exec.sender_id = Some(0);
3332	        middle_exec.destinations = Some(vec![local_destination(root_id.clone())]);
3333	        middle.params = Some(middle_exec);
3334	
3335	        let mut leaf = fragment_params(Some(scan_plan(0, 0)), Some(desc_table()));
3336	        leaf.fragment.as_mut().unwrap().output_sink = Some(data_stream_sink(7));
3337	        let mut leaf_exec = exec_params(query_id.clone(), leaf_id.clone());
3338	        leaf_exec.sender_id = Some(0);
3339	        leaf_exec.destinations = Some(vec![local_destination(middle_id.clone())]);
3340	        leaf.params = Some(leaf_exec);
3341	
3342	        (root, middle, leaf)
3343	    }
